/**
 * GitLab webhook channel pack for agent-serve.
 *
 * ```ts
 * import { defaultGitLabAuth, gitlabChannel } from "@grok/agent-sdk/channels/gitlab";
 *
 * export default gitlabChannel({
 *   // Named, not read: locally `process.env.GITLAB_WEBHOOK_SECRET`; hosted,
 *   // the deployment secret, which the control plane checks at ingestion.
 *   webhookSecret: { secretName: "GITLAB_WEBHOOK_SECRET" },
 *   onMergeRequest: (ctx) => ({ auth: defaultGitLabAuth(ctx) }),
 *   onNote: (ctx) => ({ auth: defaultGitLabAuth(ctx) }),
 * });
 * ```
 *
 * Direct webhook mode compares the project hook's `X-Gitlab-Token` against
 * {@link GitLabChannelOptions.webhookSecret} (or `GITLAB_WEBHOOK_SECRET`).
 * Hosted deployments receive deliveries the Cursor backend already
 * verified: a named `webhookSecret` lets the control plane compare the
 * token before any compute starts (architecture `v2` requires that form)
 * and strip it before the guest sees the request. The turn principal is `gitlab-webhook` plus the GitLab actor —
 * not the Cursor subscriber — matching GitHub's `github-webhook` pattern.
 */
export * from "./api.js";
export { buildGitLabBinding, gitlabDraftMarkedReady, gitlabMergeRequestFromRecord, gitlabMergeRequestUrl, gitlabProjectFromPayload, normalizeGitLabNoteableType, } from "./binding.js";
export * from "./checks.js";
export { CURSOR_GITLAB_MAX_PROJECTS, parseCursorGitLabProjectScope, resolveCursorGitLabProxyUrl, } from "./cursor-account.js";
export * from "./defaults.js";
export * from "./events.js";
export * from "./gitlab-channel.js";
export * from "./gitlab-webhook.js";
export * from "./replay.js";
export * from "./state.js";
export * from "./types.js";
